using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering.Universal;using Demo6.Game;using Demo6.Core.Combat;using Newtonsoft.Json;using Object=UnityEngine.Object;
public static class OgreSlamV051Review {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;const string Out="검증/v049-final/ogre-heavy-slam";
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);
